/* CRM Domestic Sale V2: filters, compact layout, team allocation drilldown and weekly/customer action flows. */
const filterState={periodMode:'month',years:[String(new Date().getFullYear())],periods:[],channels:[],sales:[],types:[],parts:[],subparts:[],products:[],statuses:[]};
let actionMode='followup',weeklyRowCount=0,selectedTeamTarget=null;
const APP_OAUTH_ID='227097865826-pp11vn2t5qtg69q8ito5nb9g9t165e47.apps.googleusercontent.com';
CONFIG.oauthClientId=APP_OAUTH_ID;
// Extended CRM schemas: category-level Plan, weekly Contact/Spot metrics.
TAB.productGroups='M_PRODUCT_GROUP';
HEAD.M_PRODUCT_GROUP=['Product_Group_ID','Product_Type','PART','SUB_PART','Base_UOM','Active','Data_Status'];
HEAD[TAB.teamTargets]=[...HEAD[TAB.teamTargets],'Product_Type','PART'];
HEAD[TAB.targets]=[...HEAD[TAB.targets],'Product_Type','PART','SUB_PART'];
HEAD[TAB.weeklyPlans]=[...HEAD[TAB.weeklyPlans],'Plan_Type','Contact_Completed'];
function categoryMasterRows(){const master=rows('productGroups').filter(x=>String(x.Active||'Y').toUpperCase()!=='N'&&String(x.Data_Status||'LIVE').toUpperCase()!=='DELETED');if(master.length)return master;const seen=new Set();return rows('items').filter(x=>x.PART&&x.SUB_PART).map(x=>{const k=[x.Product_Type,x.PART,x.SUB_PART].join('|');if(seen.has(k))return null;seen.add(k);return {Product_Group_ID:k,Product_Type:x.Product_Type,PART:x.PART,SUB_PART:x.SUB_PART,Base_UOM:x.Base_UOM||'',Active:'Y',Data_Status:x.Data_Status||'LIVE'}}).filter(Boolean)}

function localToday(){const d=new Date();return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`}
function isoWeek(d0){const d=new Date(`${normDate(d0)}T00:00:00Z`);if(Number.isNaN(d.getTime()))return '';d.setUTCDate(d.getUTCDate()+4-(d.getUTCDay()||7));const y=d.getUTCFullYear(),yearStart=new Date(Date.UTC(y,0,1));const w=Math.ceil((((d-yearStart)/86400000)+1)/7);return `W${String(w).padStart(2,'0')}/${y}`}
function toWeekRange(week){const m=String(week).match(/^W(\d{1,2})\/(\d{4})$/);if(!m)return {start:'',end:''};const year=+m[2],n=+m[1],jan4=new Date(Date.UTC(year,0,4)),day=jan4.getUTCDay()||7;const monday=new Date(jan4);monday.setUTCDate(jan4.getUTCDate()-day+1+(n-1)*7);const sunday=new Date(monday);sunday.setUTCDate(monday.getUTCDate()+6);return {start:monday.toISOString().slice(0,10),end:sunday.toISOString().slice(0,10)}}
function rowDate(r){return normDate(r.Due_Date||r.Plan_Date||r.Sales_Date||r.Created_Date||'')}
function allDates(){return [...rows('actuals'),...rows('actions'),...rows('weeklyPlans')].map(rowDate).filter(Boolean)}
function availableYears(){return [...new Set([...allDates().map(x=>x.slice(0,4)),...rows('teamTargets').map(x=>String(x.Year)),String(new Date().getFullYear())])].sort()}
function availablePeriods(){const years=filterState.years;const dates=allDates().filter(d=>!years.length||years.includes(d.slice(0,4)));if(filterState.periodMode==='day')return [...new Set(dates)].sort().map(v=>[v,v]);if(filterState.periodMode==='week')return [...new Set(dates.map(isoWeek))].filter(Boolean).sort().map(v=>[v,v.replace('/','/').replace(/^W/,'WEEK ')]);return [...new Set([...dates.map(d=>d.slice(0,7)),...rows('teamTargets').map(t=>`${t.Year}-${String(t.Month).padStart(2,'0')}`)])].sort().map(v=>[v,`${new Date(`${v}-01T00:00:00`).toLocaleString('en-US',{month:'short'}).toUpperCase()}/${v.slice(0,4)}`])}
function selected(key,value){return (filterState[key]||[]).includes(String(value))}
function multiFilter(key,label,options){const vals=filterState[key]||[],all=!vals.length;const summary=all?'ทั้งหมด':vals.length<3?vals.map(v=>options.find(o=>String(o[0])===v)?.[1]||v).join(', '):`${vals.length} รายการ`;return `<details class="multi-filter"><summary>${esc(label)} <b>${esc(summary)}</b></summary><div class="multi-menu"><label class="multi-option all"><input type="checkbox" data-pick-all="${key}" ${all?'checked':''}> ทั้งหมด</label>${options.map(([v,l])=>`<label class="multi-option"><input type="checkbox" data-pick="${key}" value="${esc(v)}" ${selected(key,v)?'checked':''}> ${esc(l)}</label>`).join('')}</div></details>`}
function filterOptions(){const products=active(rows('items'));const groups=categoryMasterRows();const types=[...new Set(groups.map(x=>x.Product_Type).filter(Boolean))].sort();const parts=[...new Set(groups.map(x=>x.PART).filter(Boolean))].sort();const subs=[...new Set(groups.map(x=>x.SUB_PART).filter(Boolean))].sort();const channel=active(rows('channels')).map(x=>[x.Channel_Code,x.Channel_Name||x.Channel_Code]);const sale=active(rows('sales')).map(x=>[x.Sale_ID,x.Sale_Name||x.Sale_ID]);const product=products.map(x=>[x.Item_Code,`${x.Item_Name||x.Item_Code} (${x.Item_Code})`]);return {years:availableYears().map(x=>[x,x]),periods:availablePeriods(),channels:channel,sales:sale,types:types.map(x=>[x,x]),parts:parts.map(x=>[x,x]),subparts:subs.map(x=>[x,x]),products:product,statuses:[['OPEN','Open'],['IN_PROGRESS','In Progress'],['DONE','Closed'],['CANCELLED','Cancelled']]}}
function filters(withStatus=false){const o=filterOptions();return `<div class="filter-panel"><div class="filter-row"><div class="field mode-field"><label>ช่วงเวลาอ้างอิง</label><select id="periodMode"><option value="day" ${filterState.periodMode==='day'?'selected':''}>รายวัน</option><option value="week" ${filterState.periodMode==='week'?'selected':''}>รายสัปดาห์</option><option value="month" ${filterState.periodMode==='month'?'selected':''}>รายเดือน</option></select></div>${multiFilter('years','ปี',o.years)}${multiFilter('periods',filterState.periodMode==='day'?'วันที่':filterState.periodMode==='week'?'สัปดาห์':'เดือน',o.periods)}${multiFilter('channels','Channel / Team',o.channels)}${multiFilter('sales','Sale',o.sales)}${multiFilter('types','ประเภทสินค้า',o.types)}${multiFilter('parts','PART',o.parts)}${multiFilter('subparts','SUB-PART',o.subparts)}${multiFilter('products','Product',o.products)}${withStatus?multiFilter('statuses','สถานะ Action',o.statuses):''}<button class="btn" id="refresh">↻ โหลดข้อมูล</button></div><div class="filter-hint">เลือกได้หลายรายการ · เลือก “ทั้งหมด” หรือเอาเครื่องหมายออกทั้งหมดเพื่อไม่จำกัดตัวกรอง</div></div>`}
function bindFilters(){const mode=$('#periodMode');if(mode)mode.onchange=()=>{filterState.periodMode=mode.value;filterState.periods=[];render()};document.querySelectorAll('[data-pick-all]').forEach(el=>el.onchange=()=>{filterState[el.dataset.pickAll]=[];render()});document.querySelectorAll('[data-pick]').forEach(el=>el.onchange=()=>{const k=el.dataset.pick;let a=new Set(filterState[k]||[]);el.checked?a.add(el.value):a.delete(el.value);filterState[k]=[...a];render()});$('#refresh')?.addEventListener('click',()=>token?loadDb():ping('เชื่อมต่อ Google Sheet ก่อนค่ะ',true))}
function passesCommon(r,date){const d=normDate(date||rowDate(r));if(!d)return false;const year=d.slice(0,4);if(filterState.years.length&&!filterState.years.includes(year))return false;const p=filterState.periodMode==='day'?d:filterState.periodMode==='week'?isoWeek(d):d.slice(0,7);if(filterState.periods.length&&!filterState.periods.includes(p))return false;const item=rows('items').find(i=>i.Item_Code===(r.Item_Code||''))||{};const customer=rows('customers').find(c=>c.Customer_Code===(r.Customer_Code||''))||{};const channel=r.Channel||customer.Channel||rows('sales').find(s=>s.Sale_ID===r.Sale_ID)?.Channel||rows('sales').find(s=>s.Sale_ID===r.Sale_ID)?.Team||'';const sale=r.Sale_ID||customer.Assigned_Sale_ID||'';const type=r.Product_Type||item.Product_Type||'';const part=r.PART||item.PART||'';const sub=r.SUB_PART||item.SUB_PART||'';const checks=[['channels',channel],['sales',sale],['types',type],['parts',part],['subparts',sub],['products',r.Item_Code||'']];return checks.every(([key,value])=>!filterState[key].length||filterState[key].includes(String(value)))}
function currentFiltered(){return rows('actuals').filter(a=>String(a.Data_Status||'LIVE').toUpperCase()==='LIVE'&&passesCommon(a,a.Sales_Date))}
function periodTargetMatch(t){const y=String(t.Year),m=String(t.Month).padStart(2,'0');if(filterState.years.length&&!filterState.years.includes(y))return false;if(filterState.periodMode==='month'&&filterState.periods.length&&!filterState.periods.includes(`${y}-${m}`))return false;if(filterState.periodMode==='week'&&filterState.periods.length&&!filterState.periods.some(w=>{let r=toWeekRange(w);let start=new Date(`${r.start}T00:00:00Z`),end=new Date(`${r.end}T00:00:00Z`),monthStart=new Date(Date.UTC(+y,+m-1,1)),monthEnd=new Date(Date.UTC(+y,+m,0));return start<=monthEnd&&monthStart<=end}))return false;if(filterState.periodMode==='day'&&filterState.periods.length&&!filterState.periods.some(d=>d.startsWith(`${y}-${m}`)))return false;return !filterState.channels.length||filterState.channels.includes(t.Channel)}
function dashboard(){const ac=currentFiltered(),qty=ac.reduce((s,a)=>s+Number(a.Qty_MT||0),0);const teams=rows('teamTargets').filter(t=>String(t.Data_Status||'LIVE').toUpperCase()==='LIVE'&&periodTargetMatch(t));const allocations=rows('targets').filter(t=>String(t.Data_Status||'LIVE').toUpperCase()==='LIVE'&&periodTargetMatch(t));const goal=teams.reduce((s,t)=>s+Number(t.Plan_MT||0),0),allocated=allocations.reduce((s,t)=>s+Number(t.Target_MT||0),0),remaining=goal-allocated;const details=salesProductReport(ac,allocations);const bySale=[...new Set([...ac.map(a=>a.Sale_ID),...allocations.map(a=>a.Sale_ID)].filter(Boolean))].map(s=>({name:rows('sales').find(x=>x.Sale_ID===s)?.Sale_Name||s,value:ac.filter(a=>a.Sale_ID===s).reduce((n,a)=>n+Number(a.Qty_MT||0),0)})).sort((a,b)=>b.value-a.value);const actionCounts=['OPEN','IN_PROGRESS','DONE','CANCELLED'].map(status=>({name:status,value:rows('actions').filter(a=>String(a.Data_Status||'LIVE').toUpperCase()==='LIVE'&&a.Status===status&&passesCommon(a,a.Due_Date)).length}));return pageHead('Dashboard','ยอดขายจริงเทียบเป้ารายบุคคล · หน่วย MT',`<button class="btn" id="exportDashboard">Export Excel</button>`)+filters()+`<section class="grid kpis"><div class="card"><div class="kpi-label">ยอดขาย Actual</div><div class="kpi-value">${fmt(qty)}</div><div class="kpi-foot">MT ตามตัวกรอง</div></div><div class="card"><div class="kpi-label">เป้าหมายทีม</div><div class="kpi-value">${fmt(goal)} MT</div><div class="kpi-foot">เป้าทีมในเดือน/ช่วงที่เลือก</div></div><div class="card"><div class="kpi-label">แบ่งให้ Sale แล้ว</div><div class="kpi-value">${fmt(allocated)} MT</div><div class="kpi-foot">${goal?fmt(allocated/goal*100,1):'0.0'}% ของ Team Target</div></div><div class="card"><div class="kpi-label">ยังไม่แบ่ง</div><div class="kpi-value ${remaining<0?'red':''}">${fmt(remaining)} MT</div><div class="kpi-foot"><span class="badge ${remaining<=0?'ok':'warn'}">Coverage ${goal?fmt(allocated/goal*100,1):'0.0'}%</span></div></div></section><div class="grid two"><div class="card"><h3>ยอดขาย Actual ตาม Sale</h3>${barChart(bySale,'MT')}</div><div class="card"><h3>จำนวน Sales Action ตามสถานะ</h3>${barChart(actionCounts,'รายการ')}</div></div><div class="card"><div class="row space"><h3>ผลการขายราย Sale / สินค้า</h3><span class="smallmuted">Plan เทียบยอดขาย Actual · MT</span></div>${salesProductTable(details)}</div><div class="grid two"><div class="card"><h3>รายละเอียดเป้าทีม / การแบ่งราย Sale</h3>${targetCoverage(teams,allocations)}</div><div class="card"><h3>ยอดขาย Actual ล่าสุด</h3>${actualTable(ac.slice().sort((a,b)=>normDate(b.Sales_Date).localeCompare(normDate(a.Sales_Date))).slice(0,12))}</div></div>`}
function barChart(data,unit){const max=Math.max(1,...data.map(x=>Number(x.value||0)));return data.length?`<div class="bar-list">${data.map(x=>`<div class="bar-row"><span title="${esc(x.name)}">${esc(x.name)}</span><div class="bar-track"><i style="width:${Math.max(2,Number(x.value||0)/max*100)}%"></i></div><b>${unit==='MT'?fmt(x.value):x.value} ${unit}</b></div>`).join('')}</div>`:`<div class="empty">ไม่มีข้อมูลในตัวกรองนี้</div>`}
function salesProductReport(actuals,allocations){const m=new Map(),key=(sale,g)=>[sale,g.Product_Type,g.PART,g.SUB_PART].join('|'),ensure=(sale,g)=>{const k=key(sale,g),o=m.get(k)||{Sale_ID:sale,Product_Type:g.Product_Type||'',PART:g.PART||'',SUB_PART:g.SUB_PART||'',Product:`รวมตาม ${g.SUB_PART||g.PART||'กลุ่มสินค้า'}`,Plan:0,Actual:0};m.set(k,o);return o};for(const p of allocations){const i=rows('items').find(x=>x.Item_Code===p.Item_Code)||{},g=groupForTarget({...p,...(!p.SUB_PART?{SUB_PART:i.SUB_PART}:{}),...(!p.PART?{PART:i.PART}:{}),...(!p.Product_Type?{Product_Type:i.Product_Type}:{})});ensure(p.Sale_ID,g).Plan+=Number(p.Target_MT||0)}for(const a of actuals){const i=rows('items').find(x=>x.Item_Code===a.Item_Code)||{};const g={Product_Type:i.Product_Type,PART:i.PART,SUB_PART:i.SUB_PART};ensure(a.Sale_ID,g).Actual+=Number(a.Qty_MT||0)}return [...m.values()].map(x=>({...x,Sale:rows('sales').find(s=>s.Sale_ID===x.Sale_ID)?.Sale_Name||x.Sale_ID,Success:x.Plan?x.Actual/x.Plan*100:null})).sort((a,b)=>b.Actual-a.Actual)}
function salesProductTable(data){return `<div class="tablewrap"><table class="compact-table"><thead><tr><th>Sale</th><th>ประเภทสินค้า</th><th>PART</th><th>SUB-PART</th><th>Product</th><th class="num">Plan MT</th><th class="num">Actual MT</th><th class="num">% Success</th></tr></thead><tbody>${data.map(x=>`<tr><td>${esc(x.Sale)}</td><td>${esc(x.Product_Type)}</td><td>${esc(x.PART)}</td><td>${esc(x.SUB_PART)}</td><td>${esc(x.Product)}</td><td class="num">${fmt(x.Plan)}</td><td class="num">${fmt(x.Actual)}</td><td class="num">${x.Success==null?'–':`${fmt(x.Success,1)}%`}</td></tr>`).join('')||`<tr><td colspan="8" class="empty">ไม่มี Plan/Actual ตามตัวกรอง</td></tr>`}</tbody></table></div>`}
function targetsPage(){const y=new Date().getFullYear(),m=new Date().getMonth()+1;return pageHead('เป้าหมายรายเดือน','ขั้นที่ 1 ตั้งเป้าทีม · ขั้นที่ 2 แบ่งเป้าราย Sale · แสดงยอดแบ่งแล้ว คงเหลือ และ Coverage')+`<div class="filters target-filter"><div class="field"><label>ปี</label><input id="tyear" type="number" value="${y}"></div><div class="field"><label>เดือน</label><select id="tmonth">${Array.from({length:12},(_,i)=>`<option value="${i+1}" ${i+1===m?'selected':''}>${String(i+1).padStart(2,'0')}</option>`).join('')}</select></div><div class="field"><label>Channel / Team</label><select id="tchannel"><option value="">ทั้งหมด</option>${active(rows('channels')).map(c=>`<option value="${esc(c.Channel_Code)}">${esc(c.Channel_Name||c.Channel_Code)}</option>`).join('')}</select></div><button class="btn" id="tshow">แสดง</button></div><div class="step-strip"><div class="step ${targetTab===1?'on':''}" data-step="1"><b>1</b><span>ตั้งเป้าหมายทีม<small>บันทึกใน CRM</small></span></div><i></i><div class="step ${targetTab===2?'on':''}" data-step="2"><b>2</b><span>แบ่งเป้าหมายราย Sale<small>ตรวจ Coverage ก่อนบันทึก</small></span></div></div><div class="tabs"><button data-tt="1" class="${targetTab===1?'active':''}">1 · ตั้งเป้าหมายทีม</button><button data-tt="2" class="${targetTab===2?'active':''}">2 · แบ่งเป้าราย Sale</button></div><div id="targetContent"></div>`}
function teamTargetsCurrent(){const y=+($('#tyear')?.value||new Date().getFullYear()),m=+($('#tmonth')?.value||new Date().getMonth()+1),ch=$('#tchannel')?.value;return rows('teamTargets').filter(x=>String(x.Data_Status||'LIVE').toUpperCase()==='LIVE'&&+x.Year===y&&+x.Month===m&&(!ch||x.Channel===ch))}
function allocationsForTeam(t){const g=groupForTarget(t);return rows('targets').filter(x=>String(x.Data_Status||'LIVE').toUpperCase()==='LIVE'&&String(x.Year)===String(t.Year)&&+x.Month===+t.Month&&x.Channel===t.Channel&&(x.SUB_PART||rows('items').find(i=>i.Item_Code===x.Item_Code)?.SUB_PART||'')===g.SUB_PART&&(!g.PART||(x.PART||rows('items').find(i=>i.Item_Code===x.Item_Code)?.PART||'')===g.PART)&&(!g.Product_Type||(x.Product_Type||rows('items').find(i=>i.Item_Code===x.Item_Code)?.Product_Type||'')===g.Product_Type))}
function drawTargets(){const team=teamTargetsCurrent(),split=rows('targets').filter(x=>String(x.Data_Status||'LIVE').toUpperCase()==='LIVE'&&+x.Year===+($('#tyear')?.value||new Date().getFullYear())&&+x.Month===+($('#tmonth')?.value||new Date().getMonth()+1)&&(!$('#tchannel')?.value||x.Channel===$('#tchannel').value));const assigned=split.reduce((n,x)=>n+Number(x.Target_MT||0),0),goal=team.reduce((n,x)=>n+Number(x.Plan_MT||0),0);if(targetTab===1){$('#targetContent').innerHTML=`<section class="grid kpis target-kpis"><div class="card"><div class="kpi-label">เป้าหมายทีมรวม</div><div class="kpi-value">${fmt(goal)} MT</div></div><div class="card"><div class="kpi-label">แบ่งให้ Sale แล้ว</div><div class="kpi-value">${fmt(assigned)} MT</div></div><div class="card"><div class="kpi-label">ยังไม่แบ่ง</div><div class="kpi-value ${goal-assigned<0?'red':''}">${fmt(goal-assigned)} MT</div></div><div class="card"><div class="kpi-label">Coverage เป้าทีม</div><div class="kpi-value">${goal?fmt(assigned/goal*100,1):'0.0'}%</div><div class="progress"><i style="width:${Math.min(100,goal?assigned/goal*100:0)}%"></i></div></div></section><div class="card"><div class="row space"><div><h3>เป้าหมายทีมที่บันทึกแล้ว</h3><div class="smallmuted">กดดูรายละเอียดเพื่อเห็นยอดแบ่งของ Sale แต่ละคนและยอดคงเหลือในแต่ละ SUB-PART</div></div><button class="btn primary" id="addTeamTarget">+ เพิ่ม / บันทึกเป้าทีม</button></div>${teamTargetTable(team)}</div>`;$('#addTeamTarget').onclick=()=>teamTargetModalV2(null);$('#targetContent').querySelectorAll('[data-team-edit]').forEach(b=>b.onclick=()=>teamTargetModalV2(team.find(x=>x._row===+b.dataset.teamEdit)));$('#targetContent').querySelectorAll('[data-team-split]').forEach(b=>b.onclick=()=>{selectedTeamTarget=team.find(x=>x._row===+b.dataset.teamSplit);targetTab=2;render();drawTargets()});$('#targetContent').querySelectorAll('[data-team-delete]').forEach(b=>b.onclick=()=>deleteTeamTarget(team.find(x=>x._row===+b.dataset.teamDelete)))}else{$('#targetContent').innerHTML=`<div class="card"><div class="row space"><div><h3>แบ่งเป้าหมายทีมให้ Sale</h3><div class="smallmuted">เลือกเป้าทีมก่อน หรือบันทึกเป้าราย Sale แล้วตรวจจำนวนแบ่งและคงเหลือ</div></div><button class="btn primary" id="addSplit">+ แบ่งเป้าหมายให้ Sale</button></div>${selectedTeamTarget?`<div class="notice">เป้าหมายที่เลือก: ${esc(selectedTeamTarget.Channel)} · ${esc(selectedTeamTarget.SUB_PART)} · ทีม ${fmt(selectedTeamTarget.Plan_MT)} MT · แบ่งแล้ว ${fmt(allocationsForTeam(selectedTeamTarget).reduce((n,x)=>n+Number(x.Target_MT||0),0))} MT · คงเหลือ ${fmt(Number(selectedTeamTarget.Plan_MT)-allocationsForTeam(selectedTeamTarget).reduce((n,x)=>n+Number(x.Target_MT||0),0))} MT</div>`:targetCoverage(team,split)}${splitTable(split)}</div>`;$('#addSplit').onclick=()=>splitModalV2(selectedTeamTarget||null,team,split)} }
function groupForTarget(t){const fromGroup=rows('productGroups').find(g=>g.SUB_PART===t.SUB_PART&&(!t.PART||g.PART===t.PART)&&(!t.Product_Type||g.Product_Type===t.Product_Type));const fromItem=rows('items').find(i=>i.SUB_PART===t.SUB_PART&&(!t.PART||i.PART===t.PART)&&(!t.Product_Type||i.Product_Type===t.Product_Type))||{};return {Product_Type:t.Product_Type||fromGroup?.Product_Type||fromItem.Product_Type||'',PART:t.PART||fromGroup?.PART||fromItem.PART||'',SUB_PART:t.SUB_PART||fromGroup?.SUB_PART||fromItem.SUB_PART||''}}
function teamTargetTable(data){return `<div class="tablewrap"><table class="compact-table"><thead><tr><th>ปี</th><th>เดือน</th><th>Channel / Team</th><th>Product Type</th><th>PART</th><th>SUB-PART</th><th class="num">Team Target (MT)</th><th class="num">แบ่งราย Sale (MT)</th><th class="num">คงเหลือ (MT)</th><th>Coverage</th><th>จัดการ</th></tr></thead><tbody>${data.map(t=>{const ss=allocationsForTeam(t),v=ss.reduce((n,x)=>n+Number(x.Target_MT||0),0),g=Number(t.Plan_MT||0);return `<tr><td>${t.Year}</td><td>${String(t.Month).padStart(2,'0')}</td><td>${esc(t.Channel)}</td><td>${esc(groupForTarget(t).Product_Type)}</td><td>${esc(groupForTarget(t).PART)}</td><td>${esc(groupForTarget(t).SUB_PART)}</td><td class="num">${fmt(g)}</td><td class="num"><details class="sale-detail"><summary>${fmt(v)} · ดู Sale ${ss.length}</summary><div class="sale-detail-pop">${ss.map(x=>`<div>${esc(rows('sales').find(s=>s.Sale_ID===x.Sale_ID)?.Sale_Name||x.Sale_ID)} <b>${fmt(x.Target_MT)} MT</b></div>`).join('')||'ยังไม่แบ่งรายคน'}</div></details></td><td class="num">${fmt(g-v)}</td><td><span class="badge ${v>=g?'ok':'warn'}">${g?fmt(v/g*100,1):'0.0'}%</span></td><td><div class="row nowrap"><button class="btn small" data-team-edit="${t._row}">แก้ไข</button><button class="btn small primary" data-team-split="${t._row}">แบ่งให้ Sale</button><button class="btn small danger" data-team-delete="${t._row}">ลบ</button></div></td></tr>`}).join('')||`<tr><td colspan="11" class="empty">ยังไม่มีเป้าหมายของเดือนนี้</td></tr>`}</tbody></table></div>`}
function targetCoverage(team,split){if(!team.length)return `<div class="empty">ยังไม่มีเป้าทีมในช่วงเวลานี้</div>`;return `<div class="coverage-list">${team.map(t=>{const a=allocationsForTeam(t),sum=a.reduce((n,x)=>n+Number(x.Target_MT||0),0),goal=Number(t.Plan_MT||0);return `<div class="coverage-line"><div class="row space"><b>${esc(t.Channel)} · ${esc(t.SUB_PART)}</b><span>${fmt(sum)} / ${fmt(goal)} MT</span></div><div class="progress"><i style="width:${Math.min(100,goal?sum/goal*100:0)}%"></i></div><div class="smallmuted">เหลือ ${fmt(goal-sum)} MT · ${goal?fmt(sum/goal*100,1):'0.0'}% · ${a.map(x=>`${esc(rows('sales').find(s=>s.Sale_ID===x.Sale_ID)?.Sale_Name||x.Sale_ID)} ${fmt(x.Target_MT)} MT`).join(' / ')||'ยังไม่แบ่งราย Sale'}</div></div>`}).join('')}</div>`}
function splitTable(data){return `<div class="tablewrap"><table class="compact-table"><thead><tr><th>ปี</th><th>เดือน</th><th>Channel</th><th>Product Type</th><th>PART</th><th>SUB-PART</th><th>Sale</th><th class="num">Target (MT)</th><th>สถานะ</th></tr></thead><tbody>${data.map(t=>{const i=rows('items').find(x=>x.Item_Code===t.Item_Code)||{};return `<tr><td>${t.Year}</td><td>${String(t.Month).padStart(2,'0')}</td><td>${esc(t.Channel)}</td><td>${esc(t.Product_Type||i.Product_Type)}</td><td>${esc(t.PART||i.PART)}</td><td>${esc(t.SUB_PART||i.SUB_PART)}</td><td>${esc(rows('sales').find(s=>s.Sale_ID===t.Sale_ID)?.Sale_Name||t.Sale_ID)}</td><td class="num">${fmt(t.Target_MT)}</td><td>${esc(t.Status||'DRAFT')}</td></tr>`}).join('')||`<tr><td colspan="9" class="empty">ยังไม่มีเป้ารายบุคคล</td></tr>`}</tbody></table></div>`}
function teamTargetModalV2(existing){const y=+($('#tyear')?.value||new Date().getFullYear()),m=+($('#tmonth')?.value||new Date().getMonth()+1),ch=$('#tchannel')?.value||'';openModal(`<div class="row space"><h3>${existing?'แก้ไขเป้าหมายทีม':'ตั้งเป้าหมายทีม'}</h3><button class="btn" id="modalClose">ปิด</button></div><div class="formgrid"><div class="field"><label>ปี</label><input id="mtY" type="number" value="${existing?.Year||y}"></div><div class="field"><label>เดือน</label><select id="mtM">${Array.from({length:12},(_,i)=>`<option value="${i+1}" ${+(existing?.Month||m)===i+1?'selected':''}>${String(i+1).padStart(2,'0')}</option>`).join('')}</select></div><div class="field"><label>Channel / Team</label><select id="mtC">${active(rows('channels')).map(x=>`<option value="${esc(x.Channel_Code)}" ${(existing?.Channel||ch)===x.Channel_Code?'selected':''}>${esc(x.Channel_Name||x.Channel_Code)}</option>`).join('')}</select></div><div class="field"><label>Product Type</label><select id="mtType">${[...new Set(categoryMasterRows().map(g=>g.Product_Type).filter(Boolean))].map(v=>`<option ${(existing?.Product_Type||'')===v?'selected':''}>${esc(v)}</option>`).join('')}</select></div><div class="field"><label>PART</label><select id="mtPart"></select></div><div class="field"><label>SUB-PART</label><select id="mtS"></select></div><div class="field"><label>เป้าหมายทีม (MT)</label><input id="mtQ" type="number" min="0" step="0.001" value="${existing?.Plan_MT||''}"></div></div><div class="row" style="justify-content:flex-end;margin-top:16px"><button class="btn primary" id="saveTeam">บันทึกเป้าหมายทีม</button></div>`);const fillTeamParts=()=>{const typ=$('#mtType').value,groups=categoryMasterRows().filter(g=>!typ||g.Product_Type===typ),parts=[...new Set(groups.map(g=>g.PART))];$('#mtPart').innerHTML=parts.map(v=>`<option ${v===(existing?.PART||groupForTarget(existing||{}).PART)?'selected':''}>${esc(v)}</option>`).join('');fillTeamSubs()};const fillTeamSubs=()=>{const subs=[...new Set(categoryMasterRows().filter(g=>(!$('#mtType').value||g.Product_Type===$('#mtType').value)&&(!$('#mtPart').value||g.PART===$('#mtPart').value)).map(g=>g.SUB_PART))];$('#mtS').innerHTML=subs.map(v=>`<option ${v===(existing?.SUB_PART||'')?'selected':''}>${esc(v)}</option>`).join('')};$('#mtType').onchange=fillTeamParts;$('#mtPart').onchange=fillTeamSubs;fillTeamParts();$('#saveTeam').onclick=async()=>{try{const o={...(existing||{}),Target_ID:existing?.Target_ID||id('TEAM'),Year:+$('#mtY').value,Month:+$('#mtM').value,Channel:$('#mtC').value,Product_Type:$('#mtType').value,PART:$('#mtPart').value,SUB_PART:$('#mtS').value,Plan_MT:+$('#mtQ').value,Updated_By:me,Updated_At:new Date().toISOString(),Data_Status:'LIVE'};if(!(o.Plan_MT>0))throw Error('กรอกเป้าหมายมากกว่า 0');const old=rows('teamTargets').find(x=>x.Target_ID!==o.Target_ID&&+x.Year===o.Year&&+x.Month===o.Month&&x.Channel===o.Channel&&x.Product_Type===o.Product_Type&&x.PART===o.PART&&x.SUB_PART===o.SUB_PART&&String(x.Data_Status||'LIVE').toUpperCase()==='LIVE');if(old)throw Error('มี Team Target รายการนี้แล้ว กรุณาแก้ไขรายการเดิม');if(existing)await updateRow(TAB.teamTargets,existing._row,o);else await append(TAB.teamTargets,[o]);closeModal();ping('บันทึกเป้าหมายทีมแล้ว');await loadDb()}catch(e){ping(e.message,true)}}}
async function deleteTeamTarget(t){if(!t||!confirm('ลบเป้าหมายทีมนี้หรือไม่? ระบบจะปฏิเสธหากมีการแบ่งยอดแล้ว'))return;try{if(allocationsForTeam(t).length)throw Error('เป้าหมายนี้มีการแบ่งให้ Sale แล้ว ต้องแก้/ลบยอดแบ่งก่อน');await updateRow(TAB.teamTargets,t._row,{...t,Data_Status:'DELETED',Updated_By:me,Updated_At:new Date().toISOString()});ping('ลบเป้าหมายทีมแล้ว');await loadDb()}catch(e){ping(e.message,true)}}
function splitModalV2(team,teams,splits){const y=team?.Year||+($('#tyear')?.value||new Date().getFullYear()),m=team?.Month||+($('#tmonth')?.value||new Date().getMonth()+1),ch=team?.Channel||$('#tchannel')?.value||'',g0=team?groupForTarget(team):{},groups=categoryMasterRows();openModal(`<div class="row space"><h3>แบ่งเป้าหมายทีมให้ Sale</h3><button class="btn" id="modalClose">ปิด</button></div><div class="notice">${team?`ทีม ${esc(team.Channel)} · ${esc(g0.Product_Type)} · ${esc(g0.PART)} / ${esc(g0.SUB_PART)} · เป้าทีม ${fmt(team.Plan_MT)} MT · แบ่งแล้ว ${fmt(allocationsForTeam(team).reduce((n,x)=>n+Number(x.Target_MT||0),0))} MT · คงเหลือ ${fmt(Number(team.Plan_MT)-allocationsForTeam(team).reduce((n,x)=>n+Number(x.Target_MT||0),0))} MT`:'เป้าราย Sale จะบันทึกในระดับ Product Type / PART / SUB-PART'}</div><div class="formgrid"><div class="field"><label>ปี</label><input id="spY" type="number" value="${y}"></div><div class="field"><label>เดือน</label><select id="spM">${Array.from({length:12},(_,i)=>`<option value="${i+1}" ${m===i+1?'selected':''}>${String(i+1).padStart(2,'0')}</option>`).join('')}</select></div><div class="field"><label>Channel / Team</label><select id="spC">${active(rows('channels')).map(x=>`<option value="${esc(x.Channel_Code)}" ${(ch||x.Channel_Code)===x.Channel_Code?'selected':''}>${esc(x.Channel_Name||x.Channel_Code)}</option>`).join('')}</select></div><div class="field"><label>Product Type</label><select id="spType">${[...new Set(groups.map(x=>x.Product_Type).filter(Boolean))].map(v=>`<option ${v===g0.Product_Type?'selected':''}>${esc(v)}</option>`).join('')}</select></div><div class="field"><label>PART</label><select id="spPart"></select></div><div class="field"><label>SUB-PART</label><select id="spSub"></select></div><div class="field"><label>Sale</label><select id="spS">${active(rows('sales')).filter(s=>(s.Channel||s.Team)===ch||!ch).map(x=>`<option value="${esc(x.Sale_ID)}">${esc(x.Sale_Name)}</option>`).join('')}</select></div><div class="field"><label>เป้าราย Sale (MT)</label><input id="spQ" type="number" min="0" step="0.001"></div></div><div class="row" style="justify-content:flex-end;margin-top:14px"><button class="btn primary" id="saveSplit">บันทึกยอดแบ่ง</button></div>`);const fillPart=()=>{const vals=[...new Set(groups.filter(x=>!$('#spType').value||x.Product_Type===$('#spType').value).map(x=>x.PART))];$('#spPart').innerHTML=vals.map(v=>`<option ${v===(g0.PART||'')?'selected':''}>${esc(v)}</option>`).join('');fillSub()};const fillSub=()=>{const vals=[...new Set(groups.filter(x=>(!$('#spType').value||x.Product_Type===$('#spType').value)&&(!$('#spPart').value||x.PART===$('#spPart').value)).map(x=>x.SUB_PART))];$('#spSub').innerHTML=vals.map(v=>`<option ${v===(g0.SUB_PART||'')?'selected':''}>${esc(v)}</option>`).join('')};$('#spType').onchange=fillPart;$('#spPart').onchange=fillSub;$('#spC').onchange=()=>{$('#spS').innerHTML=active(rows('sales')).filter(x=>(x.Channel||x.Team)===$('#spC').value).map(x=>`<option value="${esc(x.Sale_ID)}">${esc(x.Sale_Name)}</option>`).join('')};fillPart();$('#saveSplit').onclick=async()=>{try{const sale=rows('sales').find(x=>x.Sale_ID===$('#spS').value),type=$('#spType').value,part=$('#spPart').value,sub=$('#spSub').value,value=+$('#spQ').value,target=team||teams.find(x=>+x.Year===+$('#spY').value&&+x.Month===+$('#spM').value&&x.Channel===$('#spC').value&&x.Product_Type===type&&x.PART===part&&x.SUB_PART===sub);if(!target)throw Error('ไม่พบเป้าหมายทีมที่ตรงกับ Channel / Product Type / PART / SUB-PART กรุณาบันทึก Team Target ก่อน');if(!sale||((sale.Channel||sale.Team)!==target.Channel))throw Error('Sale ต้องอยู่ใน Channel/Team เดียวกับเป้าทีม');const used=allocationsForTeam(target).reduce((n,x)=>n+Number(x.Target_MT||0),0);if(!(value>0)||used+value>Number(target.Plan_MT)+.0001)throw Error(`ยอดแบ่งเกินเป้าทีม: คงเหลือ ${fmt(Number(target.Plan_MT)-used)} MT`);const o={Target_ID:id('SPLIT'),Year:+$('#spY').value,Month:+$('#spM').value,Channel:$('#spC').value,Item_Code:'',Product_Type:type,PART:part,SUB_PART:sub,Target_MT:value,Status:'DRAFT',External_Target_Sheet:'',Data_Status:'LIVE',Updated_By:me,Sale_ID:sale.Sale_ID,Plan_Qty:value,Plan_UOM:'MT',KG_Per_UOM:1000,Plan_KG:value*1000,Target_KG:value*1000,Quota_UOM:'MT',Updated_At:new Date().toISOString()};await append(TAB.targets,[o]);closeModal();ping('แบ่งเป้าหมายราย Sale แล้ว');await loadDb()}catch(e){ping(e.message,true)}}}

function actionPage(){return pageHead('Sales Action','จัดการแผนลูกค้ามีฐานและ Action ติดตาม · ตาราง / Kanban / ปฏิทิน',`<button class="btn primary" id="newAction">+ เพิ่ม Action</button>`)+filters(true)+`<div class="mode-tabs"><button data-action-mode="base" class="${actionMode==='base'?'active':''}">ลูกค้ามีฐาน · Plan รายสัปดาห์</button><button data-action-mode="followup" class="${actionMode==='followup'?'active':''}">ลูกค้าไม่มีฐาน / Prospect</button></div><div class="tabs"><button data-at="table" class="${actTab==='table'?'active':''}">ตาราง</button><button data-at="kanban" class="${actTab==='kanban'?'active':''}">Kanban</button><button data-at="calendar" class="${actTab==='calendar'?'active':''}">ปฏิทิน</button></div>${actionMode==='base'?weeklyPlansView():`<div class="card" id="actionContent"></div>`}`}
function weeklyPlansView(){const w=isoWeek(localToday());return `<div class="filters"><div class="field"><label>สัปดาห์สำหรับเพิ่ม/แก้ไขแผน</label><select id="weeklyWeek">${weekChoices().map(x=>`<option value="${x}" ${x===w?'selected':''}>${x.replace(/^W/,'WEEK ')}</option>`).join('')}</select></div><div class="field"><label>Sale ที่ต้องการแสดง / ผู้วางแผน</label><select id="weeklySale"><option value="">ทั้งหมด</option>${active(rows('sales')).map(x=>`<option value="${esc(x.Sale_ID)}">${esc(x.Sale_Name)}</option>`).join('')}</select></div><div class="row"><button class="btn" id="cloneWeek">ดึงแผนสัปดาห์ก่อน</button><button class="btn primary" id="newWeekly">+ บันทึกแผนสัปดาห์</button></div></div><div class="card" id="actionContent"><div class="row space"><div><h3>ลูกค้าที่มีฐานการใช้</h3><div class="smallmuted">ใช้ตัวกรองช่วงเวลา/Channel/Sale/สินค้าเดียวกันทั้งตาราง Kanban และปฏิทิน</div></div><span class="badge">Contact / Spot · UOM ตาม Master</span></div></div>`}
function weekChoices(){const set=new Set();for(let i=-10;i<=10;i++){const d=new Date(`${localToday()}T12:00:00`);d.setDate(d.getDate()+i*7);set.add(isoWeek(d.toISOString().slice(0,10)))}rows('weeklyPlans').forEach(x=>x.Week_Key&&set.add(x.Week_Key));return [...set].filter(Boolean).sort((a,b)=>{const x=toWeekRange(a).start,y=toWeekRange(b).start;return x.localeCompare(y)})}
function weeklyPlanTable(list){const weeks=filterState.periodMode==='week'?filterState.periods:[],sale=$('#weeklySale')?.value;const cur=list.filter(x=>(!weeks.length||weeks.includes(x.Week_Key))&&(!sale||x.Sale_ID===sale));return `<div class="tablewrap"><table class="compact-table"><thead><tr><th>วันที่</th><th>Sale</th><th>ประเภท Plan</th><th>ลูกค้า</th><th>Product Type</th><th>PART / SUB-PART</th><th>สินค้า</th><th class="num">Plan</th><th>หน่วย</th><th class="num">Plan MT</th><th class="num">Actual MT</th><th>Contact สำเร็จ / %</th><th></th></tr></thead><tbody>${cur.map(x=>{const c=rows('customers').find(y=>y.Customer_Code===x.Customer_Code)||{},i=rows('items').find(y=>y.Item_Code===x.Item_Code)||{};const range=toWeekRange(x.Week_Key),actual=rows('actuals').filter(a=>a.Sale_ID===x.Sale_ID&&a.Customer_Code===x.Customer_Code&&a.Item_Code===x.Item_Code&&normDate(a.Sales_Date)>=range.start&&normDate(a.Sales_Date)<=range.end).reduce((n,a)=>n+Number(a.Qty_MT||0),0);const pct=x.Plan_Type==='Contact'?contactAcceptancePct(x):null;return `<tr><td>${esc(normDate(x.Plan_Date))}</td><td>${esc(rows('sales').find(y=>y.Sale_ID===x.Sale_ID)?.Sale_Name||x.Sale_ID)}</td><td>${esc(x.Plan_Type||'Spot')}</td><td>${esc(c.Customer_Name||x.Customer_Code)}</td><td>${esc(i.Product_Type)}</td><td>${esc(i.PART)} / ${esc(i.SUB_PART)}</td><td>${esc(i.Item_Name||x.Item_Code)}</td><td class="num">${fmt(x.Plan_Qty,3)}</td><td>${esc(x.Plan_UOM)}</td><td class="num">${fmt(x.Plan_MT,3)}</td><td class="num">${fmt(actual,3)}</td><td>${x.Plan_Type==='Contact'?`${fmt(x.Contact_Completed||0,3)} ${esc(x.Plan_UOM||'')} / ${pct==null?'0.0':fmt(pct,1)}%`:'–'}</td><td><div class="row nowrap"><button class="btn small" data-week-edit="${esc(x.Plan_ID)}">แก้ไข</button><button class="btn small danger" data-week-del="${esc(x.Plan_ID)}">ลบ</button></div></td></tr>`}).join('')||`<tr><td colspan="13" class="empty">ยังไม่มีแผนในสัปดาห์ที่เลือก</td></tr>`}</tbody></table></div>`}
function contactAcceptancePct(p){const plan=Number(p.Plan_Qty||0);return plan>0?Number(p.Contact_Completed||0)/plan*100:null}
function weekRowHTML(o={},n=0){return `<div class="plan-entry" data-week-row="${n}"><div class="row space"><b>รายการแผน ${n+1}</b><button type="button" class="btn small danger" data-remove-week="${n}">ลบรายการ</button></div><div class="formgrid"><div class="field"><label>ประเภทแผน</label><select data-w-type><option ${o.Plan_Type==='Contact'?'selected':''}>Contact</option><option ${o.Plan_Type==='Spot'?'selected':''}>Spot</option></select></div><div class="field"><label>วันที่ตามคิว</label><input data-w-date type="date" value="${esc(normDate(o.Plan_Date)||localToday())}"></div><div class="field"><label>ลูกค้า</label><select data-w-customer>${active(rows('customers')).map(c=>`<option value="${esc(c.Customer_Code)}" ${o.Customer_Code===c.Customer_Code?'selected':''}>${esc(c.Customer_Name)} · ${esc(c.Customer_Code)}</option>`).join('')}</select></div><div class="field"><label>สินค้า</label><select data-w-item>${active(rows('items')).map(i=>`<option value="${esc(i.Item_Code)}" ${o.Item_Code===i.Item_Code?'selected':''}>${esc(i.Item_Name)} · ${esc(i.Item_Code)}</option>`).join('')}</select></div><div class="field"><label>จำนวน Plan</label><input data-w-qty type="number" min="0" step="0.001" value="${esc(o.Plan_Qty||'')}"></div><div class="field"><label>หน่วย</label><select data-w-uom>${uomOptionsHTML(o.Item_Code,o.Plan_UOM)}</select></div><div class="field contact-count ${o.Plan_Type==='Contact'?'':'hidden'}"><label>ปริมาณ Contact ที่รับได้ (หน่วยเดียวกับ Plan)</label><input data-w-contact type="number" min="0" step="0.001" value="${esc(o.Contact_Completed||'0')}"></div></div></div>`}
function uomOptionsHTML(itemCode,selectedUom){const item=rows('items').find(i=>i.Item_Code===itemCode),u=rows('itemUoms').filter(x=>x.Item_Code===itemCode&&String(x.Active||'Y').toUpperCase()!=='N');const list=u.length?u:item?[{UOM:item.Base_UOM||'MT',KG_Per_UOM:item.KG_Per_UOM||1000,Is_Default:'Y'}]:[];return list.map(x=>`<option value="${esc(x.UOM)}" data-kg="${esc(x.KG_Per_UOM)}" ${selectedUom===x.UOM||(!selectedUom&&String(x.Is_Default).toUpperCase()==='Y')?'selected':''}>${esc(x.UOM)} · ${fmt(x.KG_Per_UOM,3)} KG/UOM</option>`).join('')}
function openWeeklyEditor(week,saleId,sourceRows=[]){if(!sourceRows.length)sourceRows=[{}];weeklyRowCount=sourceRows.length;openModal(`<div class="row space"><div><h3>แผนลูกค้ามีฐาน · ${esc(week)}</h3><div class="smallmuted">กำหนดพนักงานครั้งเดียว แล้วเพิ่มคิวลูกค้า/สินค้าได้หลายรายการ</div></div><button class="btn" id="modalClose">ปิด</button></div><div class="formgrid"><div class="field"><label>Week / Year</label><select id="wWeek">${weekChoices().map(x=>`<option ${x===week?'selected':''}>${x}</option>`).join('')}</select></div><div class="field"><label>พนักงาน</label><select id="wSale">${active(rows('sales')).map(s=>`<option value="${esc(s.Sale_ID)}" ${saleId===s.Sale_ID?'selected':''}>${esc(s.Sale_Name)}</option>`).join('')}</select></div><div class="field"><label>Channel (จาก Sale Master)</label><input id="wChannel" readonly></div></div><div class="row space" style="margin:16px 0"><h3>รายการ Plan</h3><button class="btn" id="addWeekRow">+ เพิ่มรายการ Plan</button></div><div id="weeklyRows">${sourceRows.map((x,i)=>weekRowHTML(x,i)).join('')}</div><div class="row" style="justify-content:flex-end;margin-top:16px"><button class="btn primary" id="saveWeekly">บันทึกแผนทั้งสัปดาห์</button></div>`);$('#wSale').onchange=()=>$('#wChannel').value=rows('sales').find(x=>x.Sale_ID===$('#wSale').value)?.Channel||rows('sales').find(x=>x.Sale_ID===$('#wSale').value)?.Team||'';$('#wSale').onchange();$('#addWeekRow').onclick=()=>{const host=$('#weeklyRows'),n=host.querySelectorAll('[data-week-row]').length;host.insertAdjacentHTML('beforeend',weekRowHTML({},n));bindWeekRows()};bindWeekRows();$('#saveWeekly').onclick=saveWeeklyBatch}
function bindWeekRows(){document.querySelectorAll('[data-remove-week]').forEach(b=>b.onclick=()=>b.closest('[data-week-row]').remove());document.querySelectorAll('[data-w-type]').forEach(s=>s.onchange=()=>s.closest('[data-week-row]').querySelector('.contact-count').classList.toggle('hidden',s.value!=='Contact'));document.querySelectorAll('[data-w-item]').forEach(s=>s.onchange=()=>{const row=s.closest('[data-week-row]'),sel=row.querySelector('[data-w-uom]'),uom=sel.value;sel.innerHTML=uomOptionsHTML(s.value,uom)})}
function buildWeeklyRecord(week,sale,e){if(!sale)throw Error('เลือกพนักงานก่อนบันทึกแผน');const range=toWeekRange(week),item=rows('items').find(i=>i.Item_Code===e.Item_Code),customer=rows('customers').find(c=>c.Customer_Code===e.Customer_Code),qty=Number(e.Plan_Qty),kg=Number(e.KG_Per_UOM||item?.KG_Per_UOM||1000),dt=normDate(e.Plan_Date);if(!item||!customer||!(qty>0)||!dt)throw Error('กรอกวันที่ ลูกค้า สินค้า และจำนวน Plan ให้ครบ');if(dt<range.start||dt>range.end)throw Error(`${dt} ไม่อยู่ในช่วง ${week}`);if(!(kg>0))throw Error('ไม่พบอัตราแปลงหน่วยของสินค้า');return {Plan_ID:e.Plan_ID||id('WPLAN'),Week_Key:week,Week_Start:range.start,Week_End:range.end,Plan_Date:dt,Sale_ID:sale.Sale_ID,Customer_Code:customer.Customer_Code,Item_Code:item.Item_Code,Channel:sale.Channel||sale.Team,Plan_Qty:qty,Plan_UOM:e.Plan_UOM,KG_Per_UOM:kg,Plan_KG:qty*kg,Plan_MT:qty*kg/1000,Version:1,Saved_By:me,Saved_At:new Date().toISOString(),Data_Status:'LIVE',Plan_Type:e.Plan_Type||'Spot',Contact_Completed:e.Plan_Type==='Contact'?Number(e.Contact_Completed||0):0,_row:Number(e._row||0)}}
async function saveWeeklyBatch(){try{const week=$('#wWeek').value,sale=rows('sales').find(x=>x.Sale_ID===$('#wSale').value),els=[...document.querySelectorAll('[data-week-row]')];if(!els.length)throw Error('เพิ่มรายการ Plan อย่างน้อย 1 รายการ');const objects=els.map(el=>{const u=el.querySelector('[data-w-uom]').selectedOptions[0];return buildWeeklyRecord(week,sale,{Plan_Date:el.querySelector('[data-w-date]').value,Customer_Code:el.querySelector('[data-w-customer]').value,Item_Code:el.querySelector('[data-w-item]').value,Plan_Qty:el.querySelector('[data-w-qty]').value,Plan_UOM:u?.value,KG_Per_UOM:u?.dataset.kg,Plan_Type:el.querySelector('[data-w-type]').value,Contact_Completed:el.querySelector('[data-w-contact]')?.value,Plan_ID:el.dataset.planId,_row:el.dataset.sheetRow})});const newRows=[];for(const o of objects){if(o._row){const old=rows('weeklyPlans').find(x=>x.Plan_ID===o.Plan_ID);o.Version=Number(old?.Version||0)+1;await updateRow(TAB.weeklyPlans,o._row,o)}else newRows.push(o)}if(newRows.length)await append(TAB.weeklyPlans,newRows);closeModal();ping(`บันทึกแผน ${week} จำนวน ${objects.length} รายการ`);await loadDb()}catch(e){ping(e.message,true)}}
async function deleteWeeklyPlan(planId){const x=rows('weeklyPlans').find(p=>p.Plan_ID===planId);if(!x||!confirm('ลบแผนรายการนี้หรือไม่?'))return;try{await updateRow(TAB.weeklyPlans,x._row,{...x,Data_Status:'DELETED',Version:Number(x.Version||0)+1,Saved_By:me,Saved_At:new Date().toISOString()});await append(TAB.actionHistory,[{History_ID:id('HIS'),Action_ID:planId,Changed_At:new Date().toISOString(),Changed_By:me,Event_Type:'WEEKLY_PLAN_DELETE',Old_Plan_MT:x.Plan_MT,Note:`ลบแผน ${x.Week_Key} / ${x.Customer_Code} / ${x.Item_Code}`}]);ping('ลบแผนรายสัปดาห์แล้ว');await loadDb()}catch(e){ping(e.message,true)}}
async function clonePreviousWeek(){const week=$('#weeklyWeek')?.value||isoWeek(localToday()),saleId=$('#weeklySale')?.value;if(!saleId){ping('เลือก Sale ที่ต้องการดึงแผนก่อนค่ะ',true);return}const current=toWeekRange(week),prevDate=new Date(`${current.start}T12:00:00Z`);prevDate.setUTCDate(prevDate.getUTCDate()-7);const prev=isoWeek(prevDate.toISOString().slice(0,10)),source=rows('weeklyPlans').filter(x=>x.Week_Key===prev&&x.Sale_ID===saleId&&String(x.Data_Status||'LIVE').toUpperCase()==='LIVE');if(!source.length){ping(`ไม่พบแผนสัปดาห์ ${prev}`,true);return}const shifted=source.map(x=>({...x,Plan_ID:'',Week_Key:week,Plan_Date:new Date(new Date(`${normDate(x.Plan_Date)}T12:00:00Z`).getTime()+7*86400000).toISOString().slice(0,10),Contact_Completed:0}));openWeeklyEditor(week,saleId,shifted)}
function openWeeklyEdit(o){openWeeklyEditor(o.Week_Key,o.Sale_ID,[o]);setTimeout(()=>{const el=document.querySelector('[data-week-row]');if(el){el.dataset.planId=o.Plan_ID;el.dataset.sheetRow=o._row}},0)}
function weekKeyForDate(d){return isoWeek(d)}
function actionDateForView(a){return normDate(a.Next_Action_Date||a.Due_Date)}
function activeActionsFiltered(){return rows('actions').filter(a=>String(a.Data_Status||'LIVE').toUpperCase()==='LIVE'&&String(a.Is_Deleted||'N').toUpperCase()!=='Y'&&passesCommon(a,a.Due_Date)&&(!filterState.statuses.length||filterState.statuses.includes(a.Status)))}
function drawActions(){if(actionMode==='base'){const sale=$('#weeklySale')?.value,plans=rows('weeklyPlans').filter(x=>String(x.Data_Status||'LIVE').toUpperCase()==='LIVE'&&passesCommon(x,x.Plan_Date)&&(!sale||x.Sale_ID===sale));if(actTab==='table')$('#actionContent').innerHTML=`<div class="row space"><div><h3>แผนลูกค้าที่มีฐานการใช้</h3><div class="smallmuted">${plans.length} รายการ · Actual เทียบรายสัปดาห์ · Contact acceptance คำนวณจากจำนวนทำสำเร็จ/จำนวน Plan</div></div></div>${weeklyPlanTable(plans)}`;else if(actTab==='kanban')$('#actionContent').innerHTML=`<div class="kanban two-lane">${['Contact','Spot'].map(t=>`<div class="kancol"><div class="row space"><b>${t}</b><span class="badge">${plans.filter(x=>(x.Plan_Type||'Spot')===t).length}</span></div>${plans.filter(x=>(x.Plan_Type||'Spot')===t).map(x=>weeklyPlanCard(x)).join('')}</div>`).join('')}</div>`;else $('#actionContent').innerHTML=weeklyCalendar(plans);$('#actionContent').querySelectorAll('[data-week-edit]').forEach(b=>b.onclick=()=>{const x=rows('weeklyPlans').find(p=>p.Plan_ID===b.dataset.weekEdit);if(x)openWeeklyEdit(x)});$('#actionContent').querySelectorAll('[data-week-del]').forEach(b=>b.onclick=()=>deleteWeeklyPlan(b.dataset.weekDel));return}const a=activeActionsFiltered();if(actTab==='table')$('#actionContent').innerHTML=`<div class="tablewrap"><table class="compact-table"><thead><tr><th>วันที่กำหนด</th><th>พนักงาน</th><th>ลูกค้า / Prospect</th><th>Product Type</th><th>PART</th><th>SUB-PART</th><th>Action / Note</th><th>สถานะ</th><th class="num">Plan MT</th><th class="num">ปิดการขาย MT</th><th>Next Action</th><th>กำหนดครั้งถัดไป</th><th>Comment หัวหน้า</th><th></th></tr></thead><tbody>${a.map(x=>actionRowV2(x)).join('')||`<tr><td colspan="14" class="empty">ไม่มี Action ตามตัวกรอง</td></tr>`}</tbody></table></div>`;else if(actTab==='kanban')$('#actionContent').innerHTML=`<div class="kanban">${['OPEN','IN_PROGRESS','DONE','CANCELLED'].map(s=>`<div class="kancol"><div class="row space"><b>${s.replace('_',' ')}</b><span class="badge">${a.filter(x=>x.Status===s).length}</span></div>${a.filter(x=>x.Status===s).map(x=>actionCard(x)).join('')}</div>`).join('')}</div>`;else $('#actionContent').innerHTML=calendarMonth(a);$('#actionContent').querySelectorAll('[data-edit]').forEach(b=>b.onclick=()=>editAction(b.dataset.edit));$('#actionContent').querySelectorAll('[data-del]').forEach(b=>b.onclick=()=>deleteAction(b.dataset.del))}
function weeklyPlanCard(x){const c=rows('customers').find(y=>y.Customer_Code===x.Customer_Code)||{},i=rows('items').find(y=>y.Item_Code===x.Item_Code)||{};return `<div class="kanitem"><b>${esc(c.Customer_Name||x.Customer_Code)}</b><div class="smallmuted">${esc(normDate(x.Plan_Date))} · ${esc(i.SUB_PART||'')}</div><p>${fmt(x.Plan_MT,3)} MT · ${esc(x.Plan_Type||'Spot')}</p><div class="row"><button class="btn small" data-week-edit="${esc(x.Plan_ID)}">ดู/แก้ไข</button><button class="btn small danger" data-week-del="${esc(x.Plan_ID)}">ลบ</button></div></div>`}
function weeklyCalendar(plans){let months=filterState.periodMode==='month'?(filterState.periods.length?filterState.periods:[...new Set(plans.map(p=>normDate(p.Plan_Date).slice(0,7)).filter(Boolean))]):[...new Set(plans.map(p=>normDate(p.Plan_Date).slice(0,7)).filter(Boolean))];if(!months.length)months=[localToday().slice(0,7)];return months.sort().map(month=>{const [y,m]=month.split('-').map(Number),start=new Date(y,m-1,1),off=(start.getDay()+6)%7,days=new Date(y,m,0).getDate(),cells=Array.from({length:off},()=>'<div class="calendar-cell blank"></div>');for(let d=1;d<=days;d++){const key=`${y}-${String(m).padStart(2,'0')}-${String(d).padStart(2,'0')}`,day=plans.filter(p=>normDate(p.Plan_Date)===key);cells.push(`<div class="calendar-cell"><b>${d}</b>${day.map(p=>`<div class="calendar-entry"><button class="calendar-event" data-week-edit="${esc(p.Plan_ID)}">${esc(rows('customers').find(c=>c.Customer_Code===p.Customer_Code)?.Customer_Name||p.Customer_Code)} · ${esc(p.Plan_Type||'Spot')}</button><button class="calendar-remove" data-week-del="${esc(p.Plan_ID)}" aria-label="ลบแผน">×</button></div>`).join('')}</div>`)}return `<section class="calendar-month"><h3>${esc(month)}</h3><div class="calendar-grid">${['จ','อ','พ','พฤ','ศ','ส','อา'].map(x=>`<div class="calendar-head">${x}</div>`).join('')}${cells.join('')}</div></section>`}).join('')}
const legacyActionFormV2=legacyActionForm;
function actionForm(existing={}){if(existing?.Action_ID)return legacyActionFormV2(existing);return actionBatchForm()}
function itemGroupOptions(key){return [...new Set(categoryMasterRows().map(i=>i[key]).filter(Boolean))].sort()}
function actionBatchForm(){const channels=active(rows('channels'));openModal(`<div class="row space"><div><h3>วางแผน Action ล่วงหน้า</h3><div class="smallmuted">เลือกพนักงาน/กลุ่มสินค้าครั้งเดียว แล้วเพิ่มรายละเอียด Plan ได้หลายรายการและบันทึกพร้อมกัน</div></div><button class="btn" id="modalClose">ปิด</button></div><div class="section-title">ข้อมูลส่วนกลางของ Action</div><div class="formgrid"><div class="field"><label>พนักงาน</label><select id="baSale">${active(rows('sales')).map(s=>`<option value="${esc(s.Sale_ID)}">${esc(s.Sale_Name)}</option>`).join('')}</select></div><div class="field"><label>Channel / Team จาก Sale Master</label><input id="baChannel" readonly></div><div class="field"><label>Product Type</label><select id="baType"><option value="">เลือก Product Type</option>${itemGroupOptions('Product_Type').map(x=>`<option>${esc(x)}</option>`).join('')}</select></div><div class="field"><label>PART</label><select id="baPart"><option value="">เลือก PART</option></select></div><div class="field"><label>SUB-PART</label><select id="baSub"><option value="">เลือก SUB-PART</option></select></div></div><div class="row space" style="margin:18px 0 10px"><div><div class="section-title">รายละเอียด Plan</div><div class="smallmuted">ลูกค้าเก่าเลือกจาก Master/กลุ่มสินค้าที่สนใจ · Prospect กรอกชื่อเอง</div></div><button type="button" class="btn" id="addActionPlan">+ เพิ่ม Plan</button></div><div id="actionPlanRows"></div><div class="row" style="justify-content:flex-end;margin-top:16px"><button class="btn primary" id="saveActionBatch">บันทึก Plan ทั้งหมด</button></div>`);$('#baSale').onchange=()=>$('#baChannel').value=rows('sales').find(x=>x.Sale_ID===$('#baSale').value)?.Channel||rows('sales').find(x=>x.Sale_ID===$('#baSale').value)?.Team||'';$('#baSale').onchange();$('#baType').onchange=()=>fillGroupParts();$('#baPart').onchange=()=>fillGroupSubs();$('#addActionPlan').onclick=()=>addActionPlanRow();fillGroupParts();fillGroupSubs();addActionPlanRow();$('#saveActionBatch').onclick=saveActionBatch}
function fillGroupParts(){const type=$('#baType').value,vals=[...new Set(categoryMasterRows().filter(i=>!type||i.Product_Type===type).map(i=>i.PART).filter(Boolean))];$('#baPart').innerHTML=`<option value="">เลือก PART</option>${vals.map(x=>`<option>${esc(x)}</option>`).join('')}`;fillGroupSubs()}
function fillGroupSubs(){const type=$('#baType').value,part=$('#baPart').value,vals=[...new Set(categoryMasterRows().filter(i=>(!type||i.Product_Type===type)&&(!part||i.PART===part)).map(i=>i.SUB_PART).filter(Boolean))];$('#baSub').innerHTML=`<option value="">เลือก SUB-PART</option>${vals.map(x=>`<option>${esc(x)}</option>`).join('')}`;document.querySelectorAll('[data-a-item]').forEach(s=>setBatchItemOptions(s))}
function batchPlanRow(n){return `<div class="plan-entry" data-action-plan="${n}"><div class="row space"><b>Plan ${n+1}</b><button type="button" class="btn small danger" data-remove-plan>ลบ</button></div><div class="formgrid"><div class="field"><label>วันที่กำหนด</label><input data-a-date type="date" value="${localToday()}"></div><div class="field"><label>ประเภท Action</label><select data-a-kind>${['โทรติดตาม','เข้าพบลูกค้า','เสนอขาย','ส่งตัวอย่าง','ติดตามราคา','อื่น ๆ'].map(x=>`<option>${x}</option>`).join('')}</select></div><div class="field"><label>ประเภทลูกค้า</label><select data-a-customer-type><option value="OLD">ลูกค้าเก่า</option><option value="PROSPECT">Prospect</option></select></div><div class="field" data-a-customer-box><label>เลือกลูกค้าเดิม</label><select data-a-customer></select></div><div class="field hidden" data-a-prospect-box><label>ชื่อ Prospect</label><input data-a-prospect placeholder="พิมพ์ชื่อลูกค้า Prospect"></div><div class="field"><label>สินค้า (ใช้กำหนดหน่วย Plan)</label><select data-a-item></select></div><div class="field"><label>Plan ปริมาณ</label><input data-a-qty type="number" min="0" step="0.001"></div><div class="field"><label>หน่วยตาม Item Master</label><select data-a-uom></select></div><div class="field wide"><label>Action / รายละเอียด</label><textarea data-a-detail placeholder="รายละเอียดที่ต้องทำ"></textarea></div></div></div>`}
function addActionPlanRow(){const box=$('#actionPlanRows'),n=box.querySelectorAll('[data-action-plan]').length;box.insertAdjacentHTML('beforeend',batchPlanRow(n));const el=box.lastElementChild;setBatchItemOptions(el.querySelector('[data-a-item]'));el.querySelector('[data-a-customer-type]').onchange=e=>{const p=e.target.value==='PROSPECT';el.querySelector('[data-a-customer-box]').classList.toggle('hidden',p);el.querySelector('[data-a-prospect-box]').classList.toggle('hidden',!p)};el.querySelector('[data-a-item]').onchange=()=>setBatchUoms(el);el.querySelector('[data-remove-plan]').onclick=()=>el.remove()}
function setBatchItemOptions(sel){const type=$('#baType')?.value,part=$('#baPart')?.value,sub=$('#baSub')?.value;const values=active(rows('items')).filter(i=>(!type||i.Product_Type===type)&&(!part||i.PART===part)&&(!sub||i.SUB_PART===sub));sel.innerHTML=values.map(x=>`<option value="${esc(x.Item_Code)}">${esc(x.Item_Name)} · ${esc(x.Item_Code)}</option>`).join('');const el=sel.closest('[data-action-plan]');if(el)setBatchUoms(el)}
function customerLovOptions(itemCode){const item=rows('items').find(x=>x.Item_Code===itemCode)||{},allLinks=rows('customerProducts').filter(x=>String(x.Active||'Y').toUpperCase()!=='N'),links=allLinks.filter(x=>(!x.Product_Type||x.Product_Type===item.Product_Type)&&(!x.PART||x.PART===item.PART)&&(!x.SUB_PART||x.SUB_PART===item.SUB_PART));const codes=new Set(links.map(x=>x.Customer_Code));const customers=active(rows('customers')).filter(c=>!allLinks.length||codes.has(c.Customer_Code));return customers.map(c=>`<option value="${esc(c.Customer_Code)}">${esc(c.Customer_Name)} · ${esc(c.Customer_Code)}</option>`).join('')}
function setBatchUoms(el){const item=rows('items').find(x=>x.Item_Code===el.querySelector('[data-a-item]').value);el.querySelector('[data-a-uom]').innerHTML=uomOptionsHTML(item?.Item_Code,'');el.querySelector('[data-a-customer]').innerHTML=customerLovOptions(item?.Item_Code)}
function buildFollowupRecords(sale,type,part,sub,entries,batch=id('BATCH')){if(!sale||!type||!part||!sub)throw Error('เลือกพนักงาน Product Type, PART และ SUB-PART ให้ครบ');if(!entries.length)throw Error('เพิ่มรายการ Plan อย่างน้อย 1 รายการ');return entries.map(e=>{const item=rows('items').find(i=>i.Item_Code===e.Item_Code),isProspect=e.Customer_Type==='PROSPECT',customer=isProspect?null:rows('customers').find(c=>c.Customer_Code===e.Customer_Code),qty=Number(e.Plan_Qty),kg=Number(e.KG_Per_UOM||item?.KG_Per_UOM||1000),due=normDate(e.Due_Date);if(!item||!(qty>0)||!due||!e.Action_Type||!e.Plan_UOM||(!isProspect&&!customer)||(isProspect&&!String(e.Prospect_Name||'').trim()))throw Error('กรอกรายละเอียด Plan ให้ครบทุกแถว');if(item.Product_Type!==type||item.PART!==part||item.SUB_PART!==sub)throw Error('สินค้าในรายการไม่ตรงกับ Product Type / PART / SUB-PART ที่เลือก');if(!(kg>0))throw Error('ไม่พบอัตราแปลงหน่วยของสินค้า');return {Action_ID:id('ACT'),Created_Date:localToday(),Due_Date:due,Sale_ID:sale.Sale_ID,Customer_Code:customer?.Customer_Code||'',Item_Code:item.Item_Code,Action_Type:e.Action_Type,Expected_Qty_MT:qty*kg/1000,Status:'OPEN',Result:e.Action_Detail||'',Next_Action:'',Data_Status:'LIVE',Channel:sale.Channel||sale.Team||'',Plan_MT:qty*kg/1000,Closed_Sales_MT:0,Parent_Action_ID:'',Is_Deleted:'N',Manager_Comment:'',Updated_By:me,Updated_At:new Date().toISOString(),Plan_Qty:qty,Plan_UOM:e.Plan_UOM,KG_Per_UOM:kg,Plan_KG:qty*kg,Closed_Sales_Qty:0,Closed_Sales_UOM:e.Plan_UOM,Prospect_ID:'',Prospect_Name:isProspect?String(e.Prospect_Name).trim():'',Batch_ID:batch,Product_Type:type,PART:part,SUB_PART:sub,Next_Action_Date:''}})}
async function saveActionBatch(){try{const sale=rows('sales').find(s=>s.Sale_ID===$('#baSale').value),type=$('#baType').value,part=$('#baPart').value,sub=$('#baSub').value,els=[...document.querySelectorAll('[data-action-plan]')],batch=id('BATCH'),entries=els.map(el=>{const u=el.querySelector('[data-a-uom]').selectedOptions[0];return {Due_Date:el.querySelector('[data-a-date]').value,Action_Type:el.querySelector('[data-a-kind]').value,Customer_Type:el.querySelector('[data-a-customer-type]').value,Customer_Code:el.querySelector('[data-a-customer]').value,Prospect_Name:el.querySelector('[data-a-prospect]').value,Item_Code:el.querySelector('[data-a-item]').value,Plan_Qty:el.querySelector('[data-a-qty]').value,Plan_UOM:u?.value,KG_Per_UOM:u?.dataset.kg,Action_Detail:el.querySelector('[data-a-detail]').value}}),objects=buildFollowupRecords(sale,type,part,sub,entries,batch);await append(TAB.actions,objects);await append(TAB.actionHistory,objects.map(o=>({History_ID:id('HIS'),Action_ID:o.Action_ID,Changed_At:new Date().toISOString(),Changed_By:me,Event_Type:'CREATE',New_Status:o.Status,New_Due_Date:o.Due_Date,New_Plan_MT:o.Plan_MT,New_Next_Action:o.Next_Action})));closeModal();ping(`บันทึก Action ${objects.length} รายการแล้ว`);await loadDb()}catch(e){ping(e.message,true)}}
function render(){if(!$('#app'))return;if(!token){$('#app').innerHTML=page==='setup'?setupPage():pageHead('CRM Domestic Sale','เชื่อมต่อ Google Sheet เพื่อเริ่มใช้งาน',`<button class="btn primary" onclick="auth()">เชื่อมต่อ Google Sheet</button>`)+`<div class="card"><div class="empty">ระบบเก็บข้อมูลบน Google Sheet ของคุณ<br>กดเชื่อมต่อ Google Sheet เพื่อเริ่มใช้งาน</div></div>`;return}if(page==='dashboard')$('#app').innerHTML=dashboard();else if(page==='targets')$('#app').innerHTML=targetsPage();else if(page==='import')$('#app').innerHTML=importPage();else if(page==='actions')$('#app').innerHTML=actionPage();else if(page==='master')$('#app').innerHTML=masterPage();bindFilters();$('#app').querySelectorAll('[data-tt],[data-step]').forEach(b=>b.onclick=()=>{targetTab=Number(b.dataset.tt||b.dataset.step);render()});if(page==='targets'){drawTargets();$('#tshow').onclick=drawTargets;['tyear','tmonth','tchannel'].forEach(k=>$('#'+k).onchange=drawTargets)}if(page==='actions'){$('#app').querySelectorAll('[data-action-mode]').forEach(b=>b.onclick=()=>{actionMode=b.dataset.actionMode;render()});if(actionMode==='base'){$('#newAction').onclick=()=>openWeeklyEditor($('#weeklyWeek').value,$('#weeklySale').value||rows('sales')[0]?.Sale_ID,[]);$('#newWeekly').onclick=()=>openWeeklyEditor($('#weeklyWeek').value,$('#weeklySale').value||rows('sales')[0]?.Sale_ID,[]);$('#cloneWeek').onclick=clonePreviousWeek;$('#weeklyWeek').onchange=()=>render();$('#weeklySale').onchange=()=>drawActions()}else $('#newAction').onclick=()=>actionForm();$('#app').querySelectorAll('[data-at]').forEach(b=>b.onclick=()=>{actTab=b.dataset.at;render()});drawActions()}if(page==='import'){$('#previewImport').onclick=previewImport;$('#downloadImportTemplate').onclick=downloadTemplate;$('#exportActual').onclick=()=>exportRows(rows('actuals').filter(x=>x.Data_Status!=='MOCK'),'T_SALES_ACTUAL')}if(page==='master'){$('#app').querySelectorAll('[data-mtab]').forEach(b=>b.onclick=()=>{mtab=b.dataset.mtab;render()});drawMaster();$('#masterAdd').onclick=()=>masterModal();$('#masterExport').onclick=()=>exportRows(rows(mtab).filter(x=>x.Data_Status!=='MOCK'),mtab);$('#masterImport').onclick=()=>$('#masterUpload').click();$('#masterUpload').onchange=e=>importMaster(e.target.files[0]);$('#masterTemplate')?.addEventListener('click',()=>downloadMasterTemplate())}$('#exportDashboard')?.addEventListener('click',()=>exportRows(salesProductReport(currentFiltered(),rows('targets').filter(periodTargetMatch)),'Dashboard_Sales'))}

// Master import merges nonblank source values, preserving existing values not supplied in a partial template.
const legacyImportMasterV2=legacyImportMaster;
async function importMaster(file){if(!file)return;try{const wb=XLSX.read(await file.arrayBuffer()),data=XLSX.utils.sheet_to_json(wb.Sheets[wb.SheetNames[0]],{defval:''});if(!data.length)throw Error('ไฟล์ไม่มีแถวข้อมูล');const tab=TAB[mtab],headers=dbHeaders[tab]||Object.keys(data[0]),key=headers[0],existing=rows(mtab),index=new Map(existing.map(x=>[String(x[key]),x])),adds=[],updates=[];for(const src of data){const code=String(src[key]??'').trim();if(!code)continue;const found=index.get(code);if(found){const merged={...found};for(const h of headers)if(src[h]!==undefined&&src[h]!=='')merged[h]=src[h];updates.push([found._row,merged])}else adds.push(Object.fromEntries(headers.map(h=>[h,src[h]??''])))}for(const [r,o] of updates)await updateRow(tab,r,o);if(adds.length)await append(tab,adds);ping(`นำเข้าข้อมูลแล้ว · เพิ่ม ${adds.length} · ปรับปรุง ${updates.length}`);await loadDb()}catch(e){ping(e.message,true)}}
function downloadMasterTemplate(){if(!window.XLSX)return ping('โหลด Excel module ไม่สำเร็จ',true);const h=dbHeaders[TAB[mtab]]||HEAD[TAB[mtab]]||Object.keys(rows(mtab)[0]||{}).filter(k=>k!=='_row');if(!h.length)return ping('ไม่พบหัวตาราง Master',true);const ws=XLSX.utils.aoa_to_sheet([h]),wb=XLSX.utils.book_new();XLSX.utils.book_append_sheet(wb,ws,mtab.slice(0,31));XLSX.writeFile(wb,`${mtab}_Import_Template.xlsx`)}
function masterPage(){const keys=['productGroups','items','customers','sales','channels','itemUoms','customerProducts','prospects'],labels={productGroups:'กลุ่มสินค้า',items:'สินค้า',customers:'ลูกค้า',sales:'พนักงาน',channels:'Channel',itemUoms:'หน่วยสินค้า',customerProducts:'กลุ่มสินค้าลูกค้า',prospects:'Prospect'};return pageHead('Master Data','จัดการกลุ่มสินค้า/Item/Customer/Sale/Channel พร้อม Import/Export Excel')+`<div class="tabs master-tabs">${keys.map(k=>`<button data-mtab="${k}" class="${k===mtab?'active':''}">${labels[k]}</button>`).join('')}</div><div id="masterContent"></div>`}
function drawMaster(){const arr=rows(mtab).filter(x=>String(x.Data_Status||'LIVE').toUpperCase()!=='DELETED');$('#masterContent').innerHTML=`<div class="card"><div class="row space"><div><h3>จัดการ Master Data</h3><div class="smallmuted">เพิ่ม · แก้ไข · ปิดใช้ · Import/Export Excel · ใช้หัวคอลัมน์ตามชีต ${esc(TAB[mtab])}</div></div><div class="row"><input type="file" id="masterUpload" accept=".xlsx,.xls,.csv" class="hidden"><button class="btn" id="masterImport">Import Excel</button><button class="btn" id="masterTemplate">ดาวน์โหลด Template</button><button class="btn" id="masterExport">Export Excel</button><button class="btn primary" id="masterAdd">+ เพิ่มข้อมูล</button></div></div><div class="tablewrap"><table class="compact-table"><thead><tr>${(dbHeaders[TAB[mtab]]||Object.keys(arr[0]||{})).filter(k=>k!=='_row').slice(0,12).map(k=>`<th>${esc(k)}</th>`).join('')}<th>จัดการ</th></tr></thead><tbody>${arr.slice(0,300).map(x=>`<tr>${(dbHeaders[TAB[mtab]]||Object.keys(x)).filter(k=>k!=='_row').slice(0,12).map(k=>`<td>${esc(x[k])}</td>`).join('')}<td><button class="btn small" data-master-edit="${x._row}">แก้ไข</button> <button class="btn small danger" data-master-del="${x._row}">ปิดใช้</button></td></tr>`).join('')||`<tr><td colspan="13" class="empty">ไม่มีข้อมูล</td></tr>`}</tbody></table></div></div>`;$('#masterContent').querySelectorAll('[data-master-edit]').forEach(b=>b.onclick=()=>masterModal(arr.find(x=>x._row===+b.dataset.masterEdit)));$('#masterContent').querySelectorAll('[data-master-del]').forEach(b=>b.onclick=()=>disableMaster(arr.find(x=>x._row===+b.dataset.masterDel)))}

function targetObjectiveTests(){const t={Year:2026,Month:10,Channel:'ตลาดสด',SUB_PART:'DMS',Plan_MT:70,Data_Status:'LIVE'},items=[{Item_Code:'a',SUB_PART:'DMS'},{Item_Code:'b',SUB_PART:'CCM'}],splits=[{Year:2026,Month:10,Channel:'ตลาดสด',Item_Code:'a',Target_MT:30,Data_Status:'LIVE'},{Year:2026,Month:10,Channel:'ตลาดสด',Item_Code:'b',Target_MT:99,Data_Status:'LIVE'}];return splits.filter(x=>x.Channel===t.Channel&&+x.Year===+t.Year&&+x.Month===+t.Month&&(items.find(i=>i.Item_Code===x.Item_Code)?.SUB_PART||'')===t.SUB_PART).reduce((n,x)=>n+Number(x.Target_MT),0)}
function runStaticSelfChecks(){const checks=[['ISO week',isoWeek('2026-09-30')==='W40/2026'],['Week range',toWeekRange('W40/2026').start==='2026-09-28'&&toWeekRange('W40/2026').end==='2026-10-04'],['Team split grouped by SUB-PART',targetObjectiveTests()===30],['UOM conversion',Math.abs((2*500)/1000-1)<1e-9],['Actual KG→MT',Math.abs(7250/1000-7.25)<1e-9]];const bad=checks.filter(x=>!x[1]);return {checks,bad}}
const selfCheck=runStaticSelfChecks();if(selfCheck.bad.length)console.error('CRM static checks failed',selfCheck.bad);else console.info('CRM static checks passed',selfCheck.checks.map(x=>x[0]));
